-- Aus QuestDialog.shn generiert (echte NA2016-Client-Datei, per eigenem Parser).
-- Siehe DOCUMENTATION.md Abschnitt 48. Enthaelt Quest-Titel, -Beschreibungen
-- und NPC-Dialogtexte, referenziert per DialogID aus QuestData.shn-Skripten
-- (Befehl 'SAY <DialogID> NPC').
DROP TABLE IF EXISTS `data_questdialog`;
CREATE TABLE `data_questdialog` (
  `DialogID` INT UNSIGNED NOT NULL,
  `Text` TEXT NOT NULL,
  PRIMARY KEY (`DialogID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

